  "drizzle.config.ts": "import { defineConfig } from \"drizzle-kit\";\n\n// `pnpm run db:generate` writes a versioned migration into drizzle/ from\n// lib/db/schema.ts (the schema is the SSOT for every table). The box's deploy\n// applies new files forward-only and refuses destructive statements; review the\n// SQL in the pull request.\nexport default defineConfig({\n  schema: \"./lib/db/schema.ts\",\n  out: \"./drizzle\",\n  dialect: \"postgresql\",\n  dbCredentials: { url: process.env.DATABASE_URL ?? \"postgres://localhost:5432/app\" },\n});\n",
  "drizzle/0000_accounts.sql": "CREATE TABLE \"accounts\" (\n\t\"id\" text PRIMARY KEY NOT NULL,\n\t\"account_id\" text NOT NULL,\n\t\"provider_id\" text NOT NULL,\n\t\"user_id\" text NOT NULL,\n\t\"access_token\" text,\n\t\"refresh_token\" text,\n\t\"id_token\" text,\n\t\"access_token_expires_at\" timestamp with time zone,\n\t\"refresh_token_expires_at\" timestamp with time zone,\n\t\"scope\" text,\n\t\"password\" text,\n\t\"created_at\" timestamp with time zone DEFAULT now() NOT NULL,\n\t\"updated_at\" timestamp with time zone DEFAULT now() NOT NULL\n);\n--> statement-breakpoint\nCREATE TABLE \"model_keys\" (\n\t\"user_id\" text PRIMARY KEY NOT NULL,\n\t\"vendor\" text NOT NULL,\n\t\"model\" text NOT NULL,\n\t\"sealed_key\" text NOT NULL,\n\t\"hint\" text NOT NULL,\n\t\"created_at\" timestamp with time zone DEFAULT now() NOT NULL,\n\t\"updated_at\" timestamp with time zone DEFAULT now() NOT NULL\n);\n--> statement-breakpoint\nCREATE TABLE \"passkeys\" (\n\t\"id\" text PRIMARY KEY NOT NULL,\n\t\"name\" text,\n\t\"public_key\" text NOT NULL,\n\t\"user_id\" text NOT NULL,\n\t\"credential_id\" text NOT NULL,\n\t\"counter\" integer NOT NULL,\n\t\"device_type\" text NOT NULL,\n\t\"backed_up\" boolean NOT NULL,\n\t\"transports\" text,\n\t\"aaguid\" text,\n\t\"created_at\" timestamp with time zone DEFAULT now(),\n\tCONSTRAINT \"passkeys_credential_id_unique\" UNIQUE(\"credential_id\")\n);\n--> statement-breakpoint\nCREATE TABLE \"sessions\" (\n\t\"id\" text PRIMARY KEY NOT NULL,\n\t\"expires_at\" timestamp with time zone NOT NULL,\n\t\"token\" text NOT NULL,\n\t\"ip_address\" text,\n\t\"user_agent\" text,\n\t\"user_id\" text NOT NULL,\n\t\"created_at\" timestamp with time zone DEFAULT now() NOT NULL,\n\t\"updated_at\" timestamp with time zone DEFAULT now() NOT NULL,\n\tCONSTRAINT \"sessions_token_unique\" UNIQUE(\"token\")\n);\n--> statement-breakpoint\nCREATE TABLE \"two_factors\" (\n\t\"id\" text PRIMARY KEY NOT NULL,\n\t\"secret\" text NOT NULL,\n\t\"backup_codes\" text NOT NULL,\n\t\"user_id\" text NOT NULL,\n\t\"verified\" boolean DEFAULT true,\n\t\"failed_verification_count\" integer DEFAULT 0,\n\t\"locked_until\" timestamp with time zone\n);\n--> statement-breakpoint\nCREATE TABLE \"users\" (\n\t\"id\" text PRIMARY KEY NOT NULL,\n\t\"name\" text DEFAULT '' NOT NULL,\n\t\"email\" text NOT NULL,\n\t\"email_verified\" boolean DEFAULT false NOT NULL,\n\t\"image\" text,\n\t\"role\" text DEFAULT 'customer' NOT NULL,\n\t\"two_factor_enabled\" boolean DEFAULT false NOT NULL,\n\t\"created_at\" timestamp with time zone DEFAULT now() NOT NULL,\n\t\"updated_at\" timestamp with time zone DEFAULT now() NOT NULL,\n\tCONSTRAINT \"users_email_unique\" UNIQUE(\"email\")\n);\n--> statement-breakpoint\nCREATE TABLE \"verifications\" (\n\t\"id\" text PRIMARY KEY NOT NULL,\n\t\"identifier\" text NOT NULL,\n\t\"value\" text NOT NULL,\n\t\"expires_at\" timestamp with time zone NOT NULL,\n\t\"created_at\" timestamp with time zone DEFAULT now() NOT NULL,\n\t\"updated_at\" timestamp with time zone DEFAULT now() NOT NULL\n);\n--> statement-breakpoint\nALTER TABLE \"accounts\" ADD CONSTRAINT \"accounts_user_id_users_id_fk\" FOREIGN KEY (\"user_id\") REFERENCES \"public\".\"users\"(\"id\") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint\nALTER TABLE \"model_keys\" ADD CONSTRAINT \"model_keys_user_id_users_id_fk\" FOREIGN KEY (\"user_id\") REFERENCES \"public\".\"users\"(\"id\") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint\nALTER TABLE \"passkeys\" ADD CONSTRAINT \"passkeys_user_id_users_id_fk\" FOREIGN KEY (\"user_id\") REFERENCES \"public\".\"users\"(\"id\") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint\nALTER TABLE \"sessions\" ADD CONSTRAINT \"sessions_user_id_users_id_fk\" FOREIGN KEY (\"user_id\") REFERENCES \"public\".\"users\"(\"id\") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint\nALTER TABLE \"two_factors\" ADD CONSTRAINT \"two_factors_user_id_users_id_fk\" FOREIGN KEY (\"user_id\") REFERENCES \"public\".\"users\"(\"id\") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint\nCREATE INDEX \"accounts_user_id_idx\" ON \"accounts\" USING btree (\"user_id\");--> statement-breakpoint\nCREATE UNIQUE INDEX \"accounts_provider_account_uidx\" ON \"accounts\" USING btree (\"provider_id\",\"account_id\");--> statement-breakpoint\nCREATE INDEX \"passkeys_user_id_idx\" ON \"passkeys\" USING btree (\"user_id\");--> statement-breakpoint\nCREATE INDEX \"sessions_user_id_idx\" ON \"sessions\" USING btree (\"user_id\");--> statement-breakpoint\nCREATE INDEX \"two_factors_user_id_idx\" ON \"two_factors\" USING btree (\"user_id\");--> statement-breakpoint\nCREATE INDEX \"two_factors_secret_idx\" ON \"two_factors\" USING btree (\"secret\");--> statement-breakpoint\nCREATE INDEX \"verifications_identifier_idx\" ON \"verifications\" USING btree (\"identifier\");",
