  "next.config.ts": "import { execFileSync } from \"node:child_process\";\nimport type { NextConfig } from \"next\";\nimport createNextIntlPlugin from \"next-intl/plugin\";\nimport { SECURITY_HEADERS } from \"./lib/security\";\n\nconst withNextIntl = createNextIntlPlugin(\"./i18n/request.ts\");\n\n/**\n * The commit this build was made from, so /api/health can say what production\n * runs (the auto-merge sweep's reconciler compares it to main). The deploy\n * builds inside GitHub Actions, where GITHUB_SHA is set; a local build asks\n * git; anything else is reported as unknown, never guessed.\n */\nfunction buildCommit(): string {\n  if (process.env.GITHUB_SHA) return process.env.GITHUB_SHA;\n  try {\n    return execFileSync(\"git\", [\"rev-parse\", \"HEAD\"], { encoding: \"utf8\" }).trim();\n  } catch {\n    return \"\";\n  }\n}\n\nconst nextConfig: NextConfig = {\n  // The box's launch.sh starts the standalone server.js.\n  output: \"standalone\",\n  reactStrictMode: true,\n  outputFileTracingIncludes: { \"/*\": [\"./content/blog/**/*\"] },\n  // Nothing to gain from telling the internet which framework this is.\n  poweredByHeader: false,\n  env: { BUILD_COMMIT: buildCommit() },\n  async headers() {\n    return [\n      { source: \"/:path*\", headers: SECURITY_HEADERS },\n      // Nothing an API answers — a session, a setting, a model's reply — may\n      // sit in a shared cache.\n      { source: \"/api/:path*\", headers: [{ key: \"Cache-Control\", value: \"no-store\" }] },\n    ];\n  },\n};\n\nexport default withNextIntl(nextConfig);\n",
  "package-plan.json": "{\n  \"blocks\": {\n    \"shell\": {\n      \"package\": \"@bitbaum/sitekit\",\n      \"bindings\": [\n        {\n          \"file\": \"app/[locale]/layout.tsx\",\n          \"symbols\": [\"SiteMasthead\", \"SiteFooter\"]\n        }\n      ]\n    },\n    \"identity\": {\n      \"package\": \"@bitbaum/accountkit\",\n      \"bindings\": [\n        {\n          \"file\": \"lib/auth/server.ts\",\n          \"symbols\": [\"createAuthRuntime\"]\n        },\n        {\n          \"file\": \"components/auth/SignInForm.tsx\",\n          \"symbols\": [\"SharedSignInForm\"]\n        }\n      ]\n    },\n    \"publishing\": {\n      \"package\": \"bip-kit\",\n      \"surfaces\": [\n        \"app/[locale]/roadmap/page.tsx\",\n        \"app/[locale]/changelog/page.tsx\",\n        \"app/[locale]/blog/page.tsx\"\n      ],\n      \"bindings\": [\n        {\n          \"file\": \"components/DevelopmentRecords.tsx\",\n          \"symbols\": [\"DevelopmentPage\"]\n        },\n        {\n          \"file\": \"app/[locale]/blog/[slug]/page.tsx\",\n          \"symbols\": [\"ArticleBody\", \"ReadingProgress\"]\n        }\n      ]\n    },\n    \"design\": {\n      \"package\": \"@bitbaum/design-tokens\",\n      \"bindings\": [\n        {\n          \"file\": \"app/globals.css\"\n        }\n      ]\n    },\n    \"chat\": {\n      \"package\": \"@bitbaum/chatkit\",\n      \"bindings\": [\n        {\n          \"file\": \"app/globals.css\"\n        },\n        {\n          \"file\": \"components/chat/SharedChat.tsx\",\n          \"symbols\": [\"ChatThread\", \"ChatStarters\", \"Composer\"]\n        }\n      ]\n    }\n  }\n}\n",
